INSERT INTO documents (title, author, type, year, lang, source, publisher, isbn, pages, tags, keywords, drive_id, url, status, access_level, entities)
VALUES ('Criteria Ringgit (1500-2014)', 'Bakar Langkawi, Dr Ibrahim', 'book', 2015, 'BM', '', '', 'Masdinar', NULL, '{"190"}', '{}', NULL, 'CERITERA RINGGIT
 
 
 (1500-2014)
 
 
 Buku ini cuba memaparkan sebuah ceritera yang ringkas tetapi menyeluruh tentang perjalanan sejarah matawang Ringgit yang pernah menjadi matawang utama di Nusantara. Sesungguhnya Ringgit telah melalui sejarah yang panjang dan mengalami suatu proses perubahan yang menarik dari awal hingga kini.', 'available', 'public', '{"people":[],"organizations":[],"countries":[],"topics":[]}');
INSERT INTO documents (title, author, type, year, lang, source, publisher, isbn, pages, tags, keywords, drive_id, url, status, access_level, entities)
VALUES ('Dunia Sama Rata', 'Friedman, Thomas L.', 'book', NULL, 'BM', '', '', 'ITBM', NULL, '{"68"}', '{}', NULL, 'Dalam buku Dunia Sama Rata ini, Thomas Friedman menjelaskan tentang dunia baru kepada pembaca, membolehkan mereka memahami peristiwa global yang membingungkan, yang mereka saksikan dengan mata sendiri. Berbekalkan keupayaan beliau yang tersendiri dalam menterjemahkan polisi luar negeri dan isu ekonomi yang kompleks, Friedman menjelaskan bagaimana perataan dunia berlaku pada awal abad ke-21 dan ini bermakna, negara, syarikat, komuniti dan individu dan bagaimana kerajaan dan masyarakat boleh dan mesti menyesuaikan diri dengan keadaan ini.
 
 Buku Dunia Sama Rata ini merupakan satu karya yang tepat pada masanya yang memberitahu kita tentang keperluan, kejayaan dan ketidakpuasan tentang globalisasi yang digarap serta digambarkan dengan berkesan oleh seorang wartawan yang dihormati.', 'available', 'public', '{"people":[],"organizations":[],"countries":[],"topics":[]}');
