VALUES ('Evaluation: A Systematic Approach', 'Rossi, Peter H.; Lipsey, Mark W.; Freeman, Howard E.', 'book', NULL, 'BM', '', '', '', NULL, '{}', '{}', NULL, 'The book that has been a benchmark in evaluation has been further improved and updated. Relied on by over 90,000 readers as "the" text on how to design, implement and appraise the utility of social programmes, the Sixth Edition of Evaluation has been completely revised to include the latest techniques and approaches, as well as guidelines for how evaluations should be tailored to fit programmes and social contexts.', 'available', 'public', '{"people":[],"organizations":[],"countries":[],"topics":[]}');
