INSERT INTO documents (title, author, type, year, lang, source, publisher, isbn, pages, tags, keywords, drive_id, url, status, access_level, entities)
VALUES ('Glanville Williams: Learning the law', 'Williams, Glanville; Smith, A.T.H.; Brode, Douglas Llewelyn', 'book', NULL, 'BM', '', '', '', NULL, '{}', '{}', NULL, 'First published in 1945, Glanville Williams: Learning the Law has been introducing students to the ''foundation'' skills needed to study law effectively for more than sixty years. Presenting an overview of the English Legal System and covering the essential legal skills that students need to master if they want to succeed both in their legal studies and in their future careers, this is a must-have book for all new law students!', 'available', 'public', '{"people":[],"organizations":[],"countries":[],"topics":[]}');
