INSERT INTO documents (title, author, type, year, lang, source, publisher, isbn, pages, tags, keywords, drive_id, url, status, access_level, entities)
VALUES ('Libraries and the Development of Civilization', 'Alatas, Syed Hussein', 'book', NULL, 'BM', '', '', 'Gerakbudaya', NULL, '{"30"}', '{}', NULL, 'Libraries and the Development of Civilizations is an essay by the late renowned Malaysian social theorist and professor, Syed Hussein Alatas. His last piece of writing before his passing in 2007, this slim volume contains his thoughts on the library as an institution and the role it plays in developing the minds of people.
 
 The reader is given a glimpse into Alatas’ book collection. Given his long career as an academic, the titles he read span a wide range of topics, emphasizing Alatas’ belief in the pivotal role of libraries in building thinking societies through the handing down of knowledge.', 'available', 'public', '{"people":[],"organizations":[],"countries":[],"topics":[]}');
INSERT INTO documents (title, author, type, year, lang, source, publisher, isbn, pages, tags, keywords, drive_id, url, status, access_level, entities)
VALUES ('Lords of the Rim 2010: The Invisible Empire of the Overseas Chinese', 'Seagrave, Sterling', 'book', NULL, 'BM', '', '', '', NULL, '{}', '{}', NULL, 'For 2,000 years, China''s merchants and adventurers have fled tyrannical dynasties to make their fortunes in other countries. Seagrave reveals for the first time the invisible empire of the Overseas Chinese, how it controls some adopted countries, and how it is tightly knit by a web of dialects, secret societies, triads, and financial networks worth over $2-trillion. Seagrave shows how the tide has reversed and rich Overseas Chinese have helped create China''s boom making it now the world''s No.1 economic power, while the West struggles to stay afloat. The result is a Chinese renaissance that has put a friendly smile on the face of the dragon in the Chinese century.', 'available', 'public', '{"people":[],"organizations":[],"countries":[],"topics":[]}');
INSERT INTO documents (title, author, type, year, lang, source, publisher, isbn, pages, tags, keywords, drive_id, url, status, access_level, entities)
VALUES ('Mein Kampf', 'Hitler, Adolf', 'book', 2011, 'BM', '', '', 'YLP Publication', NULL, '{"467"}', '{}', NULL, 'MEIN KAMPF is perhaps the only notable work written in two volumes by Adolf Hitler, in 1924. Hitler was arrested when he took out a mass demonstration in favour of national unity for the formation of a social-ist German state. He was tried by the People''s Court in Munich and subsequently, imprisoned for thirteen months where he wrote the first volume. The second volume was written after he was released. Mein Kampf will give you an insight into one of the greatest evil geniuses of the last century; his political ideals, his beliefs and motiva-tion, and his struggle to consolidate Germany into one great nation, and a Nazi-third Reich.', 'available', 'public', '{"people":[],"organizations":[],"countries":[],"topics":[]}');
