INSERT INTO documents (title, author, type, year, lang, source, publisher, isbn, pages, tags, keywords, drive_id, url, status, access_level, entities)
VALUES ('Republik Tiongkok (1914-1929)', 'Wicaksono, Michael', 'book', NULL, 'BM', '', '', 'Elex Media Komputindo', NULL, '{"658"}', '{}', NULL, 'Buku ini akan menceritakan sejarah berdirinya Republik Tiongkok, diawali dari kegagalan sistem kekaisaran mempertahankan dukungan rakyat akibat serangkaian kekalahan perang yang diperparah oleh kebobrokan pemerintahan akibat korupsi, revolusi berdarah yang melahirkan Republik Tiongkok, sampai upaya untuk mempersatukan kembali Tiongkok yang terpecah akibat persaingan kepentingan, dan diakhiri dengan perpecahan yang masih bertahan sampai sekarang antara ideologi Nasionalis dan Komunis. Buku ini juga akan menceritakan kehidupan berbagai figur penting dari berbagai kubu yang pernah hidup di Tiongkok, sebagai bahan pembelajaran bagi generasi sekarang akan pentingnya memahami seluk-beluk persaingan politik dan pertentangan kepentingan dalam sebuah negara yang demokratis sekalipun.', 'available', 'public', '{"people":[],"organizations":[],"countries":[],"topics":[]}');
