INSERT INTO documents (title, author, type, year, lang, source, publisher, isbn, pages, tags, keywords, drive_id, url, status, access_level, entities)
VALUES ('The 9/11 Commission Report: Final Report of the National Commission on Terrorist Attacks Upon the United States', 'States, National Commission on Terrorist Attacks Upon the United', 'book', NULL, 'BM', '', '', '', NULL, '{}', '{}', NULL, 'Nearly three thousand people died in the terrorist attacks of September 11, 2001. In Lower Manhattan, on a field in Pennsylvania, and along the banks of the Potomoc, the United States suffered the single largest loss of life from an enemy attack on its soil. In November 2002 the United States Congress and President George W. Bush established by law the National Commission on Terrorist Attacks Upon the United States, also known as the 9/11 Commission. This independent, bipartisan panel was directed to examine the facts and circumstances surrounding the September 11 attacks, identify lessons learned, and provide recommendations to safeguard against future acts of terrorism. This volume is the authorized edition of the Commission''s final report. 
This volume is the authorized edition of the Commission''s final report.', 'available', 'public', '{"people":[],"organizations":[],"countries":[],"topics":[]}');
INSERT INTO documents (title, author, type, year, lang, source, publisher, isbn, pages, tags, keywords, drive_id, url, status, access_level, entities)
VALUES ('The Audacity of Hope: Thoughts on Reclaiming the American Dream', 'Obama, Barack', 'book', NULL, 'BM', '', '', 'Crown Publishers', NULL, '{}', '{}', NULL, 'The Audacity of Hope is Barack Obama''s call for a new kind of politics—a politics that builds upon those shared understandings that pull us together as Americans. Lucid in his vision of America''s place in the world, refreshingly candid about his family life and his time in the Senate, Obama here sets out his political convictions and inspires us to trust in the dogged optimism that has long defined us and that is our best hope going forward.', 'available', 'public', '{"people":[],"organizations":[],"countries":[],"topics":[]}');
