VALUES ('Tribes, Treaties, and Constitutional Tribulations', 'Jr., Vine Deloria; Wilkins, David E.', 'book', 2000, 'BM', '', '', 'University of Texas Press', NULL, '{"244"}', '{}', NULL, '"Two prominent scholars of American Indian law and politics undertake a full historical examination of the relationship between Indians and the United States Constitution that explains the present state of confusion and inconsistent application in U.S. Indian law." -- Jacket.', 'available', 'public', '{"people":[],"organizations":[],"countries":[],"topics":[]}');
INSERT INTO documents (title, author, type, year, lang, source, publisher, isbn, pages, tags, keywords, drive_id, url, status, access_level, entities)
VALUES ('Why the Germans? Why the Jews?: Envy, Race Hatred, and the Prehistory of the Holocaust', 'Aly, Götz', 'book', NULL, 'BM', '', '', '', NULL, '{}', '{}', NULL, 'Warum die Juden? Warum die Deutschen? Diese beiden Fragen harren seit 1945 einer Antwort. Götz Aly gelangt in seinem neuen Buch zu verstörenden Einsichten. Er beschreibt Fortschrittsscheu, Bildungsmangel und Freiheitsangst so vieler christlicher Deutscher während des 19. und zu Beginn des 20. Jahrhunderts. Dagegen begeisterten sich die deutschen Juden für das Stadtleben, für höhere Bildung; sie wussten die Chancen der Moderne zu nutzen. Die trägen Nicht-Juden sahen ihnen mit Neid und Missgunst hinterher. Aus Schwäche erwuchsen zuerst Sehnsucht nach kollektiver Stärke, dann Rassendünkel und am Ende mörderischer Antisemitismus. Götz Aly ermöglicht es, den Holocaust als Teil der deutschen Geschichte zu verstehen.', 'available', 'public', '{"people":[],"organizations":[],"countries":[],"topics":[]}');
