INSERT INTO documents (title, author, type, year, lang, source, publisher, isbn, pages, tags, keywords, drive_id, url, status, access_level, entities)
VALUES ('A World Without Meaning: The crisis of meaning in international politics', 'Zaki Laïdi', 'book', 1998, 'BM', '1Z9aKC11VZjuJ2Cpf1RnEQdU7VPn5kclO', 'Routledge', '', NULL, '{"198"}', '{"crisis of meaning","international politics","globalization","Cold War","Enlightenment","identity","power","market democracy","nationalism","Europe","Japan","America"}', 'https://drive.google.com/file/d/1Z9aKC11VZjuJ2Cpf1RnEQdU7VPn5kclO/view?usp=drivesdk', 'Buku ini menganalisis krisis makna dalam politik antarabangsa selepas berakhirnya Perang Dingin, yang bukan sahaja menamatkan komunisme tetapi juga era Pencerahan. Pengarang berhujah bahawa globalisasi telah menyebabkan keretakan antara makna dan kuasa, di mana negara-negara dan aktor sosial lain bergelut untuk mencari identiti dan tujuan dalam dunia yang sentiasa berubah. Ia menyoroti cabaran untuk membina semula makna kolektif tanpa bergantung pada ideologi besar atau matlamat akhir yang jelas.', 'digital', 'public', '{"people":[],"organizations":[],"countries":[],"topics":[]}');
INSERT INTO documents (title, author, type, year, lang, source, publisher, isbn, pages, tags, keywords, drive_id, url, status, access_level, entities)
VALUES ('A World Without Meaning', 'Zaki Laïdi', 'book', 1998, 'BM', '1Z9aKC11VZjuJ2Cpf1RnEQdU7VPn5kclO', 'Routledge', '', NULL, '{"198"}', '{"international politics","globalization","Cold War","meaning crisis","Enlightenment","identity","power","state","market democracy","nationalism","Europe","Japan","America"}', 'https://drive.google.com/file/d/1Z9aKC11VZjuJ2Cpf1RnEQdU7VPn5kclO/view?usp=drivesdk', 'Buku ini menganalisis krisis makna dalam politik antarabangsa pasca-Perang Dingin, di mana globalisasi telah menyebabkan keruntuhan ideologi dan sistem teleologi yang memberikan makna kepada dunia. Zaki Laïdi berhujah bahawa berakhirnya Perang Dingin bukan sahaja menamatkan komunisme tetapi juga cara berfikir yang berasal dari Zaman Pencerahan, menyebabkan kesukaran untuk memahami dunia yang semakin global. Ia meneroka bagaimana negara-negara dan aktor sosial bergelut untuk mencari identiti dan tujuan dalam dunia tanpa matlamat akhir yang jelas, sering kembali kepada model lama yang tidak lagi berkesan.', 'digital', 'public', '{"people":[],"organizations":[],"countries":[],"topics":[]}');
INSERT INTO documents (title, author, type, year, lang, source, publisher, isbn, pages, tags, keywords, drive_id, url, status, access_level, entities)
VALUES ('LAPORAN PERKEMBANGAN STRATEGIK ANTARABANGSA, SERANTAU & NASIONAL JANUARI-JUN 2022', 'Asyraf Farique', 'report', 2022, 'BM', '1YqA7IzRGL9z98OQpSGD5ZimL3ICgZq5S', 'Interdisciplinary Research and International Strategy (IRIS) Institute Berhad', '', NULL, '{"250"}', '{"Laporan Strategik","Perkembangan Antarabangsa","Perkembangan Serantau","Perkembangan Nasional","Geopolitik","Ekonomi","Keselamatan","Malaysia","Rusia-Ukraine","China-Amerika Syarikat"}', 'https://drive.google.com/file/d/1YqA7IzRGL9z98OQpSGD5ZimL3ICgZq5S/view?usp=drivesdk', 'Laporan ini adalah penilaian strategik terhadap perkembangan semasa yang dipantau oleh IRIS INSTITUTE, merangkumi konteks, perkembangan dan penilaian strategik percaturan kuasa di peringkat antarabangsa, serantau dan nasional dari Januari hingga Jun 2022. Ia menganalisis impak Perang Rusia-Ukraine, persaingan China-Amerika Syarikat di Asia Pasifik dan Malaysia, serta perkembangan strategik kuasa nasional, termasuk isu ekonomi, keselamatan dan politik domestik. Laporan ini bertujuan membantu pemegang taruh memahami impak perkembangan semasa terhadap perancangan strategik dan membuat keputusan terbaik.', 'digital', 'public', '{"people":[],"organizations":[],"countries":[],"topics":[]}');
INSERT INTO documents (title, author, type, year, lang, source, publisher, isbn, pages, tags, keywords, drive_id, url, status, access_level, entities)
VALUES ('LAPORAN STRATEGIK KUASA NASIONAL MALAYSIA 2024-2025', 'IRIS Institute', 'article', 2025, 'BM', '1R-lM2C8J9NVASTctQXe7bSe4Q0lDWZ2_', 'IRIS Institute Berhad', '', NULL, '{"350"}', '{"Kuasa Nasional","Malaysia","Strategik","Politik","Pentadbiran","Undang-undang","Hubungan Luar","Keselamatan","Pertahanan","Ekonomi","Teknologi","Pendidikan","Media","Sosial","Identiti","Budaya","Autonomi Sabah Sarawak","Pengaruh China","Basic Structure Doctrine","Normalisasi Israel","Laut China Selatan","Industri Pertahanan","Kedaulatan Data","Ekonomi Bumiputera","Pelaburan Asing","Tenaga","Keselamatan Makanan","Kartel","Pendidikan Populis","Warga China","Populasi Muda","Identiti Cina","Desentralisasi Kuasa Borneo","Penjajahan AI","Perebutan Sumber Tenaga","Zionisme","Pengamerikaan"}', 'https://drive.google.com/file/d/1R-lM2C8J9NVASTctQXe7bSe4Q0lDWZ2_/view?usp=drivesdk', 'Laporan Strategik Kuasa Nasional 2024-2025 ini menganalisis trend strategik nasional dalam politik, ekonomi, sosial, dan keselamatan, serta implikasinya terhadap Kuasa Nasional Malaysia. Ia menyoroti cabaran seperti vakum agenda Melayu, tuntutan autonomi Borneo, dominasi teknologi asing, dan ancaman keselamatan makanan, yang kesemuanya berpotensi menggugat kedaulatan dan kestabilan negara.', 'digital', 'public', '{"people":[],"organizations":[],"countries":[],"topics":[]}');
INSERT INTO documents (title, author, type, year, lang, source, publisher, isbn, pages, tags, keywords, drive_id, url, status, access_level, entities)
VALUES ('Malaysia-Indonesia Conflict', 'A.G. Mezerik', 'article', 1965, 'BM', '1yPs6qEyU1ABEbV6HpxePV7-fHM6VE_Fm', 'International Review Service, Inc.', '', NULL, '{"122"}', '{"Malaysia","Indonesia","Konfrontasi","United Nations","Sukarno","Tunku Abdul Rahman","Cold War","Southeast Asia","Decolonization","Sabah","Sarawak","Singapore","Brunei","Philippines"}', 'https://drive.google.com/file/d/1yPs6qEyU1ABEbV6HpxePV7-fHM6VE_Fm/view?usp=drivesdk', 'Laporan ini mengupas konflik Malaysia-Indonesia (Konfrontasi) yang timbul selepas penubuhan Malaysia pada tahun 1963. Ia merangkumi dasar "Ganyang Malaysia" oleh Indonesia, penglibatan PBB, tuntutan Filipina, penarikan diri Indonesia dari PBB, serta peranan kuasa besar. Dokumen ini juga menyediakan kronologi peristiwa dan lampiran dokumen rasmi.', 'digital', 'public', '{"people":[],"organizations":[],"countries":[],"topics":[]}');
INSERT INTO documents (title, author, type, year, lang, source, publisher, isbn, pages, tags, keywords, drive_id, url, status, access_level, entities)
VALUES ('The Spear and the Kerambit: The Exploits of VAT 69, Malaysia''s Elite Fighting Force 1968-1989', 'A. Navaratnam', 'book', 2001, 'BM', '1KxvMs0tWiK-bR9SJDJmhPSpcmFtQX1Y2', 'Utusan Publications & Distributors Sdn Bhd', '', NULL, '{"205"}', '{"VAT 69","Malaysia","Communist Party of Malaya","counter-insurgency","Special Air Service","jungle warfare","police field force"}', 'https://drive.google.com/file/d/1KxvMs0tWiK-bR9SJDJmhPSpcmFtQX1Y2/view?usp=drivesdk', 'Buku ini mengisahkan eksploitasi VAT 69, pasukan elit Malaysia, dalam memerangi pengganas komunis dari tahun 1968 hingga 1989. Ia memperincikan pembentukan unit, latihan, dan operasi mereka dalam perang gerila hutan. Buku ini juga menyoroti peranan VAT 69 dalam menjejaki dan melumpuhkan rangkaian sokongan komunis, serta sumbangan mereka kepada keamanan dan kestabilan di Malaysia.', 'digital', 'public', '{"people":[],"organizations":[],"countries":[],"topics":[]}');
INSERT INTO documents (title, author, type, year, lang, source, publisher, isbn, pages, tags, keywords, drive_id, url, status, access_level, entities)
VALUES ('ESG Is Mainly Top-Down Planning by Elites', 'Matthew Lau', 'article', 2023, 'BM', '1C_ORs_apYwIm5mw9X-dym2q-vKlvo2U9', 'Fraser Institute', '', NULL, '{"11"}', '{"ESG","corporate social responsibility","stakeholder capitalism","top-down planning","elites","government policy","central banks","financial regulation","World Economic Forum","Canada Pension Plan Investment Board"}', 'https://drive.google.com/file/d/1C_ORs_apYwIm5mw9X-dym2q-vKlvo2U9/view?usp=drivesdk', 'Esei ini berpendapat bahawa ESG (Environmental, Social, and Governance) adalah inisiatif utama yang didorong oleh elit, bukan permintaan dari bawah oleh investor atau konsumen. Ia menyoroti peran pemerintah, bank sentral, regulator keuangan, dan organisasi seperti World Economic Forum dalam memaksakan agenda ESG, yang seringkali dianggap sebagai bentuk perencanaan terpusat dan sosialisme. Penulis menyimpulkan bahawa fokus pada ESG mengalihkan perhatian dari tujuan utama bisnis untuk meningkatkan keuntungan, yang secara tidak langsung juga berkontribusi pada kesejahteraan masyarakat.', 'digital', 'public', '{"people":[],"organizations":[],"countries":[],"topics":[]}');
INSERT INTO documents (title, author, type, year, lang, source, publisher, isbn, pages, tags, keywords, drive_id, url, status, access_level, entities)
VALUES ('Ringkasan Eksekutif Rancangan Malaysia Kedua Belas', 'Kerajaan Malaysia', 'article', 2021, 'BM', '1vpghCJWJ4Kol_2qK5eT-XtHkcuti58WC', 'Unit Perancang Ekonomi, Jabatan Perdana Menteri', '', NULL, '{"19"}', '{"Rancangan Malaysia Kedua Belas","RMKe-12","ekonomi","sosioekonomi","kemampanan","inklusif","makmur","COVID-19","Wawasan Kemakmuran Bersama 2030","Matlamat Pembangunan Mampan","SDG","transformasi","pembangunan negara"}', 'https://drive.google.com/file/d/1vpghCJWJ4Kol_2qK5eT-XtHkcuti58WC/view?usp=drivesdk', 'Rancangan Malaysia Kedua Belas (RMKe-12) 2021-2025 adalah pelan transformasi negara yang bertujuan untuk mencapai Malaysia yang makmur, inklusif dan mampan, berlandaskan semangat Keluarga Malaysia. Ia memberi tumpuan kepada penjanaan semula ekonomi, pengukuhan keselamatan, kesejahteraan dan inklusiviti, serta melonjakkan kemampanan, disokong oleh pemangkin dasar untuk bakat, teknologi, infrastruktur dan perkhidmatan awam. Pelan ini juga menangani cabaran pandemik COVID-19 dan ketidakpastian ekonomi global, serta menjamin pemulihan ekonomi yang mampan dan perlindungan sosial.', 'digital', 'public', '{"people":[],"organizations":[],"countries":[],"topics":[]}');
INSERT INTO documents (title, author, type, year, lang, source, publisher, isbn, pages, tags, keywords, drive_id, url, status, access_level, entities)
VALUES ('RANCANGAN MALAYSIA KESEBELAS 2016-2020', 'Dato’ Sri Mohd Najib bin Tun Haji Abdul Razak', 'article', 2015, 'BM', '193V4b-Tllv3jfsPsA0Xn9R9ZFbODKjWo', 'Unit Perancang Ekonomi, Jabatan Perdana Menteri, Malaysia', '', NULL, '{"388"}', '{"Rancangan Malaysia Kesebelas","pertumbuhan berpaksikan rakyat","ekonomi makro","inklusiviti","kesejahteraan rakyat","modal insan","pertumbuhan hijau","infrastruktur","produktiviti","inovasi","pembangunan ekonomi","perkhidmatan awam","Wawasan 2020"}', 'https://drive.google.com/file/d/193V4b-Tllv3jfsPsA0Xn9R9ZFbODKjWo/view?usp=drivesdk', 'Rancangan Malaysia Kesebelas (RMKe-11) 2016-2020 adalah pelan pembangunan lima tahun terakhir untuk merealisasikan Wawasan 2020, bertujuan menjadikan Malaysia negara maju yang inklusif dan mampan. Ia berteraskan prinsip "Bangsa Malaysia" dan menumpukan kepada pertumbuhan berpaksikan rakyat, dengan produktiviti dan inovasi sebagai tonggak utama. Pelan ini menggariskan enam teras strategik dan enam pemacu perubahan untuk meningkatkan taraf hidup, kemakmuran, dan kesejahteraan rakyat secara berterusan, memastikan tiada rakyat Malaysia yang terpinggir.', 'digital', 'public', '{"people":[],"organizations":[],"countries":[],"topics":[]}');
INSERT INTO documents (title, author, type, year, lang, source, publisher, isbn, pages, tags, keywords, drive_id, url, status, access_level, entities)
VALUES ('RANCANGAN MALAYSIA KE-8', 'DR. MAHATHIR BIN MOHAMAD', 'article', 2001, 'BM', '1M68ynSfe34Kb3afFFDHkrBTyfniP-flx', 'Kerajaan Malaysia', '', NULL, '{"518"}', '{"Rancangan Malaysia Kelapan","RMK-8","ekonomi makro","pembangunan wilayah","pembasmian kemiskinan","pembangunan sumber manusia","infrastruktur","tenaga","sains dan teknologi","teknologi maklumat dan komunikasi","kewangan","pelancongan","perdagangan pengedaran","kesihatan","perumahan","perkhidmatan sosial","alam sekitar","pengurusan sumber asli","wanita dan pembangunan","belia dalam pembangunan","kerjasama antarabangsa","pembaharuan pentadbiran"}', 'https://drive.google.com/file/d/1M68ynSfe34Kb3afFFDHkrBTyfniP-flx/view?usp=drivesdk', 'Rancangan Malaysia Kelapan (RMKe-8) menggariskan langkah-langkah pembangunan negara untuk tempoh 2001-2005, bertujuan mencapai perpaduan dan kemajuan mengikut Wawasan 2020. Ia memberi tumpuan kepada pertumbuhan mampan, pengukuhan daya tahan ekonomi, pembasmian kemiskinan, penyusunan semula masyarakat, dan pembangunan sumber manusia berasaskan pengetahuan. Rancangan ini juga menekankan peningkatan daya saing, penggunaan ICT, serta pengurusan alam sekitar yang mampan.', 'digital', 'public', '{"people":[],"organizations":[],"countries":[],"topics":[]}');
INSERT INTO documents (title, author, type, year, lang, source, publisher, isbn, pages, tags, keywords, drive_id, url, status, access_level, entities)
VALUES ('SUMBER MINERAL NEGARA 2019', '', 'article', 2019, 'BM', '1WzxUpvnn03PdzYtdgTVyy0jtDZ7lHMfG', '', '', NULL, '{"4"}', '{"sumber mineral","mineral berlogam","mineral perindustrian","pasir","arang batu","Malaysia","pengeluaran mineral","nilai anggaran"}', 'https://drive.google.com/file/d/1WzxUpvnn03PdzYtdgTVyy0jtDZ7lHMfG/view?usp=drivesdk', 'Dokumen ini menyajikan data komprehensif mengenai sumber mineral di Malaysia untuk tahun 2019. Ia merangkumi anggaran sumber dan nilai mineral berlogam, mineral perindustrian, pasir, dan mineral tenaga, serta butiran pengeluaran mineral mengikut jenis dan nilai. Data ini memberikan gambaran keseluruhan tentang kekayaan mineral negara dan aktiviti perlombongan pada tahun tersebut.', 'digital', 'public', '{"people":[],"organizations":[],"countries":[],"topics":[]}');
INSERT INTO documents (title, author, type, year, lang, source, publisher, isbn, pages, tags, keywords, drive_id, url, status, access_level, entities)
VALUES ('Rancangan Malaysia Kesepuluh', 'Dato’ Sri Mohd Najib bin Tun Abdul Razak', 'article', 2010, 'BM', '1C0_VLySEkNIsSroavQwkb72L73Y_SZov', 'Unit Perancang Ekonomi, Jabatan Perdana Menteri', '', NULL, '{"472"}', '{"Rancangan Malaysia Kesepuluh","ekonomi berpendapatan tinggi","transformasi ekonomi","Wawasan 2020","1Malaysia","Program Transformasi Kerajaan","Model Baru Ekonomi","pembangunan inklusif","modal insan","produktiviti","inovasi","kualiti hidup","alam sekitar","perkhidmatan awam","Masyarakat Perdagangan dan Perindustrian Bumiputera"}', 'https://drive.google.com/file/d/1C0_VLySEkNIsSroavQwkb72L73Y_SZov/view?usp=drivesdk', 'Rancangan Malaysia Kesepuluh (RMKe-10) 2011-2015 ini menggariskan strategi komprehensif untuk mentransformasikan Malaysia ke arah menjadi negara maju berpendapatan tinggi menjelang Wawasan 2020. Ia memfokuskan kepada pertumbuhan ekonomi yang dipacu produktiviti dan inovasi, pembangunan modal insan bertaraf dunia, serta memastikan pembangunan sosioekonomi yang inklusif dan mampan untuk semua rakyat. Pelan ini menekankan peranan sektor swasta sebagai pemacu utama pertumbuhan dan pembaharuan perkhidmatan awam berorientasikan rakyat.', 'digital', 'public', '{"people":[],"organizations":[],"countries":[],"topics":[]}');
INSERT INTO documents (title, author, type, year, lang, source, publisher, isbn, pages, tags, keywords, drive_id, url, status, access_level, entities)
VALUES ('Ringkasan Eksekutif Rancangan Malaysia Kesebelas 2016-2020', 'Unit Perancang Ekonomi, Jabatan Perdana Menteri, Malaysia', 'article', 2015, 'BM', '1fqFLHSSdnG8YTx8z3Ep3jffGjhvkYKAt', 'Percetakan Nasional Malaysia Berhad', '', NULL, '{"44"}', '{"Pertumbuhan berpaksikan rakyat","ekonomi makro","produktiviti","kesejahteraan rakyat","modal insan","pertumbuhan hijau","infrastruktur","inovasi","bandar berdaya saing","perkhidmatan awam","Wawasan 2020"}', 'https://drive.google.com/file/d/1fqFLHSSdnG8YTx8z3Ep3jffGjhvkYKAt/view?usp=drivesdk', 'Rancangan Malaysia Kesebelas (RMKe-11) 2016-2020 merupakan pelan pembangunan lima tahun terakhir untuk merealisasikan Wawasan 2020, berfokuskan rakyat untuk meningkatkan taraf hidup dan kemakmuran negara. Pelan ini menggariskan enam teras strategik dan enam pemacu perubahan untuk mencapai status negara maju dan inklusif, dengan penekanan pada ekonomi makro yang mantap, inklusiviti, kesejahteraan rakyat, modal insan berkemahiran, pertumbuhan hijau, infrastruktur, dan perkhidmatan awam berproduktiviti tinggi.', 'digital', 'public', '{"people":[],"organizations":[],"countries":[],"topics":[]}');
INSERT INTO documents (title, author, type, year, lang, source, publisher, isbn, pages, tags, keywords, drive_id, url, status, access_level, entities)
VALUES ('Dasar Tenaga Negara 2022-2040', 'Unit Perancang Ekonomi, Jabatan Perdana Menteri', 'article', 2022, 'BM', '1N8Ae9r8ZPesJPvcymUbpgiEZOkl1Jqif', 'Unit Perancang Ekonomi, Jabatan Perdana Menteri', '', NULL, '{"73"}', '{"Dasar Tenaga Negara","peralihan tenaga","ekonomi hijau","tenaga boleh baharu","kelestarian alam sekitar","jaminan bekalan tenaga","pengurangan GHG","pembangunan sosioekonomi","Malaysia"}', 'https://drive.google.com/file/d/1N8Ae9r8ZPesJPvcymUbpgiEZOkl1Jqif/view?usp=drivesdk', 'Dasar Tenaga Negara (DTN) 2022-2040 menggariskan hala tuju strategik Malaysia untuk sektor tenaga, memfokuskan kepada peralihan tenaga ke arah sumber yang lebih bersih dan mampan. Ia bertujuan untuk memacu pertumbuhan sosioekonomi, memastikan jaminan bekalan tenaga, dan meningkatkan kelestarian alam sekitar. DTN juga menetapkan sasaran pengurangan pelepasan gas rumah kaca (GHG) dan menggalakkan pelaburan dalam teknologi rendah karbon serta tenaga boleh baharu.', 'digital', 'public', '{"people":[],"organizations":[],"countries":[],"topics":[]}');
INSERT INTO documents (title, author, type, year, lang, source, publisher, isbn, pages, tags, keywords, drive_id, url, status, access_level, entities)
VALUES ('Mukadimah Perjuangan Melayu: Sorotan Sejarah Perjuangan 500SM-2016M', '', 'article', 2017, 'BM', '1FrERy8iqnsOCK0yDG7zlHTP3OHf7nNDR', '', '', NULL, '{"335"}', '{"Melayu","perjuangan","politik","sejarah","penjajahan","Cina","British","Islam","ekonomi","sosialisme","global","Freemason","Fabian Society","Malayan Union","Dasar Ekonomi Baru","PPSMI","One Belt One Road","Pivot to Asia","demokrasi","liberalisme","LGBT","BERSIH"}', 'https://drive.google.com/file/d/1FrERy8iqnsOCK0yDG7zlHTP3OHf7nNDR/view?usp=drivesdk', 'Buku ini mengisahkan landskap politik dan perjuangan ummah Melayu Islam dari awal kewujudannya hingga kini, menyoroti manifestasi kemahuan bangsa Melayu untuk berdaulat di tanah air sendiri dan peranan Islam dalam keagungan tamadun mereka. Ia menganalisis ancaman luar dari Cina dan Barat, serta peranan Freemason dan Fabian Society dalam mencatur nasib bangsa Melayu, sambil merangkumkan respons dan perjuangan orang Melayu menentang penjajahan. Buku ini bertujuan untuk membina kesedaran ummah mengenai cabaran global dan agenda politik yang mempengaruhi survival Melayu-Islam.', 'digital', 'public', '{"people":[],"organizations":[],"countries":[],"topics":[]}');
INSERT INTO documents (title, author, type, year, lang, source, publisher, isbn, pages, tags, keywords, drive_id, url, status, access_level, entities)
VALUES ('Edisi 67 (Mei 2023) Perkembangan Pelaburan Langsung Asing (FDI) China di Malaysia', 'Unknown', 'article', 2023, 'BM', '1m1hAEyqysNPNs3GwLpRxLsrMZWvKYgrt', 'Unknown', '', NULL, '{}', '{"FDI","China","Malaysia","Pelaburan Langsung Asing","Ekonomi"}', 'https://docs.google.com/document/d/1m1hAEyqysNPNs3GwLpRxLsrMZWvKYgrt/edit?usp=drivesdk&ouid=102328783937852177686&rtpof=true&sd=true', 'Dokumen ini menganalisis perkembangan Pelaburan Langsung Asing (FDI) dari China di Malaysia. Ia memfokuskan pada data dan tren terkini sehingga Mei 2023, memberikan gambaran mengenai aliran pelaburan dua hala.', 'digital', 'public', '{"people":[],"organizations":[],"countries":[],"topics":[]}');
