INSERT INTO documents (title, author, type, year, lang, source, publisher, isbn, pages, tags, keywords, drive_id, url, status, access_level, entities)
VALUES ('Deep State: Tinjauan Kes di beberapa buah negara', 'Aiman Faudzi, Fahmi Bahrudin, Asyraf Farique', 'article', 2021, 'BM', '1nanbibSw_caLza6vvb9Uhxi2tJIDr_2x', 'IRIS Institute Berhad', '', NULL, '{"55"}', '{"deep state","shadow state","chaebol","kongsi","triad","secret societies","politik","ekonomi","kerajaan tidak rasmi","kuasa di sebalik kuasa"}', 'https://drive.google.com/file/d/1nanbibSw_caLza6vvb9Uhxi2tJIDr_2x/view?usp=drivesdk', 'Laporan ini mengkaji konsep ''deep state'' sebagai ''kuasa di sebalik kuasa'' atau ''kerajaan tidak rasmi'' dalam sains politik, menganalisis struktur, jaringan, dan modus operandinya di beberapa negara. Ia membandingkan deep state dengan konsep serupa seperti shadow state, chaebol, kongsi, dan secret societies. Kajian ini bertujuan memperluas pemahaman tentang deep state dan membuka ruang untuk kajian lanjut, terutamanya di Malaysia.', 'digital', 'public', '{"people":[],"organizations":[],"countries":[],"topics":[]}');
INSERT INTO documents (title, author, type, year, lang, source, publisher, isbn, pages, tags, keywords, drive_id, url, status, access_level, entities)
VALUES ('Sejarah Rekrutmen Elit Global di Malaysia', 'Unit Analisis IRIS Institute', 'article', 2021, 'BM', '1lPkcawysIlQF626PlYXCpjeRpwbEIiyO', 'Interdisciplinary Research and International Strategy (IRIS) Institute Berhad', '', NULL, '{"28"}', '{"rekrutmen elit","British","Malaysia","pendidikan","Fabian Society","Freemason","Orde Baru Dunia","Anglophile","Malay College Kuala Kangsar","Sultan Idris Training College"}', 'https://drive.google.com/file/d/1lPkcawysIlQF626PlYXCpjeRpwbEIiyO/view?usp=drivesdk', 'Strategi rekrutmen Elit Global di Malaysia oleh British bertujuan melahirkan proksi tempatan yang berjiwa Anglophile untuk melaksanakan polisi dalam kerangka Orde Baru Dunia. Ini dilakukan melalui institusi pendidikan elit seperti Malay College Kuala Kangsar dan penglibatan dalam pertubuhan rahsia seperti Fabian Society dan Freemason. Elit Melayu yang direkrut kemudian mengisi jawatan strategik dalam pentadbiran negara pasca-kemerdekaan, memastikan dasar negara selaras dengan kehendak Orde Baru Dunia.', 'digital', 'public', '{"people":[],"organizations":[],"countries":[],"topics":[]}');
INSERT INTO documents (title, author, type, year, lang, source, publisher, isbn, pages, tags, keywords, drive_id, url, status, access_level, entities)
VALUES ('Bank Negara: Sejarah & Evolusi Pengawalan Order Ekonomi Dunia', 'Unit Analisis IRIS Institute', 'article', 2021, 'BM', '1b6bzs6rJdqgGWr5v6gz3h9sEOYXIf4uY', 'Interdisciplinary Research and International Strategy (IRIS) Institute Berhad', '', NULL, '{"29"}', '{"Bank Negara Malaysia","sejarah","evolusi","pengawalan ekonomi","order ekonomi dunia","institusi kewangan antarabangsa","Bretton Woods","IMF","World Bank","neo-kolonialisme","kapitalis Yahudi"}', 'https://drive.google.com/file/d/1b6bzs6rJdqgGWr5v6gz3h9sEOYXIf4uY/view?usp=drivesdk', 'Laporan ini mengkaji sejarah dan evolusi Bank Negara Malaysia (BNM) serta peranannya dalam pengawalan order ekonomi dunia, bermula dari pengaruh institusi kewangan antarabangsa seperti Bank of England dan Bretton Woods Institutions. Ia menyoroti penubuhan BNM pada tahun 1959 sebagai hasil lobi antarabangsa dan persaingan antara kelompok Anglophile dan Nasionalis. Kajian ini juga menganalisis keterikatan BNM dengan institusi kewangan global seperti IBRD, World Bank, IMF, dan BIS, yang menunjukkan batasan negara dalam menentukan dasar institusi tersebut.', 'digital', 'public', '{"people":[],"organizations":[],"countries":[],"topics":[]}');
INSERT INTO documents (title, author, type, year, lang, source, publisher, isbn, pages, tags, keywords, drive_id, url, status, access_level, entities)
VALUES ('Sustainable Development Goals (SDGs) dan New World Order (NWO)', 'Fahmi Bahrudin', 'article', 2021, 'BM', '1R3e4YJf7iXUhXgNOg0StsIULLfWNMahk', 'Interdisciplinary Research and International Strategy (IRIS) Institute Berhad', '', NULL, '{"19"}', '{"Sustainable Development Goals","New World Order","Malthusian Theory","Limits to Growth","Orde Dunia Baru","Global Governance","PBB","IMF","Bank Dunia"}', 'https://drive.google.com/file/d/1R3e4YJf7iXUhXgNOg0StsIULLfWNMahk/view?usp=drivesdk', 'Penulisan ini mengkaji agenda Sustainable Development Goals (SDG) dan kaitannya dengan kerangka besar New World Order (NWO). Ia meneliti peranan Club of Rome, sebuah ''think tank'' yang agenda utamanya adalah untuk menyempurnakan penstrukturan Orde Baru Dunia, sebagai pemain utama dalam kewujudan SDG. Agenda SDG menggunakan platform global seperti PBB, Bank Dunia, dan IMF untuk memastikan tujuannya mencapai segenap lapisan manusia di semua negara, dengan implementasi merangkumi strategi top-bottom dan bottom-up.', 'digital', 'public', '{"people":[],"organizations":[],"countries":[],"topics":[]}');
