INSERT INTO documents (title, author, type, year, lang, source, publisher, isbn, pages, tags, keywords, drive_id, url, status, access_level, entities)
VALUES ('A HISTORY of the ARAB PEOPLES', 'Albert Hourani', 'article', 2013, 'BM', '1_ni2ksJhPyXrTz05YIq3XHyo1I-HDBRD', 'Faber and Faber Ltd', '', NULL, '{"649"}', '{"Arab history","Islam","Ottoman Empire","European empires","Arab nationalism","Middle East","North Africa","Ibn Khaldun","Arab Spring","Palestine conflict","Sufism","Shari''a"}', 'https://drive.google.com/file/d/1_ni2ksJhPyXrTz05YIq3XHyo1I-HDBRD/view?usp=drivesdk', 'Buku ini mengisahkan sejarah masyarakat Arab dari kebangkitan Islam hingga ke zaman moden, meliputi pembentukan empayar, masyarakat Muslim, dan pengaruh empayar Uthmaniyyah serta Eropah. Ia menganalisis perubahan sosial, politik, dan budaya, termasuk kebangkitan nasionalisme Arab dan cabaran kontemporari seperti ''Arab Spring'' dan konflik Palestin. Penulis menggunakan kerangka Khaldunian untuk memahami dinamika kekuasaan dan perpaduan dalam masyarakat Arab.', 'digital', 'public', '{"people":[],"organizations":[],"countries":[],"topics":[]}');
INSERT INTO documents (title, author, type, year, lang, source, publisher, isbn, pages, tags, keywords, drive_id, url, status, access_level, entities)
VALUES ('Transformed by the People: Hayat Tahrir al-Sham’s Road to Power in Syria', 'Patrick Haenni & Jerome Drevon', 'article', 2024, 'BM', '1t_ivdgWTHUjaGJSQSjwjKDpoPcLokOv0', 'Hurst & Company, London', '', NULL, '{"250"}', '{"Hayat Tahrir al-Sham","HTS","Syria","jihadism","deradicalisation","Salafism","governance","political Islam","Thermidorian","Sunni identity politics","revolutionary movements","Idlib","political authoritarianism"}', 'https://drive.google.com/file/d/1t_ivdgWTHUjaGJSQSjwjKDpoPcLokOv0/view?usp=drivesdk', 'Buku ini menganalisis transformasi Hayat Tahrir al-Sham (HTS) daripada kumpulan jihadi kepada aktor politik pragmatik di Syria, menumpukan kepada deradikalisasi, penyelarasan semula ideologi, dan pengukuhan kuasa di Idlib. Ia meneroka bagaimana HTS menyesuaikan diri dengan tekanan tempatan dan antarabangsa, beralih daripada Salafisme radikal dan jihad global sambil menguruskan perbezaan dalaman dan hubungan luar, yang memuncak dengan pengambilalihan Damsyik pada tahun 2024.', 'digital', 'public', '{"people":[],"organizations":[],"countries":[],"topics":[]}');
INSERT INTO documents (title, author, type, year, lang, source, publisher, isbn, pages, tags, keywords, drive_id, url, status, access_level, entities)
VALUES ('50 Politics Classics: Freedom Equality Power: Mind-Changing, World-Changing Ideas from Fifty Landmark Books (50 Classics)', 'Butler-Bowdon, Tom', 'book', NULL, 'BM', '', '', '', NULL, '{}', '{}', NULL, 'From Abraham Lincoln to Nelson Mandela, and from Aristotle to George Orwell, 50 POLITICS CLASSICS distills the essence of the books, pamphlets, and speeches of the major leaders and great thinkers that drive real-world change. Spanning 2,500 years, left and right, thinkers and doers, Tom Butler-Bowdon''s new book covers activists, war strategists, visionary leaders, economists, philosophers of freedom, feminists, conservatives and environmentalists, right up to contemporary classics such as The Spirit Level and No Logo. 
 
 Whether you consider yourself to be conservative, liberal, socialist, or Marxist, this book gives you greater understanding of the key ideas that matter in our politically charged times.', 'available', 'public', '{"people":[],"organizations":[],"countries":[],"topics":[]}');
