INSERT INTO documents (title, author, type, year, lang, source, publisher, isbn, pages, tags, keywords, drive_id, url, status, access_level, entities)
VALUES ('Cruel Peace: Living Through the Cold War', 'Inglis, Fred', 'book', NULL, 'BM', '', '', 'Aurum Press Ltd', NULL, '{"512"}', '{}', NULL, 'The Cruel Peace is an unforgettable saga of the epoch that has shaped our lives, chronicling the impact of the Cold War from the arenas of global politics to the psychic interior of our private fears and phobias. Fred Inglis combines vivid renderings of the cockpits of superpower confrontation--Berlin, Korea, Cuba, Budapest, Prague, Vietnam--with the recollections of frontline participants--George Kennan, Lord Carrington, Willy Brandt, Freeman Dyson, Joan Didion, and others. Inglis''s pungent readings of the era''s best known imaginative fictions which helped make moral sense and nonsense of Cold War ideology and myth--films like The Manchurian Candidate and Dr. Strangelove; novels like The Spy Who Came In from the Cold and The Hunt For Red October--enhance our understanding.

The Cruel Peace marries the public spectacles of military and diplomatic maneuvers to the feel of everyday life and action in a portrayal of mutual loss, hypocrisy, and cruelty in a war with no winners. While faithfully recounting the great standoffs of the Cold War, from the Berlin blockade to Afghanistan, Inglis subjects the posturing and self-serving propaganda of ruling elites and their governments to scathing criticism. An epoch so full of waste and deceit need not have turned out that way, he argues. And when everything came crashing down in 1989, Inglis shows that this resulted from as much as anything else a spontaneous revulsion on the part of a new generation against the lies of its parents.

The Cruel Peace transcends conventional history, weaving together dramatic chronicles, political tall tales, biography, interviews, film, television, and literature to convey the sense and substance of this misbegotten half-century.', 'available', 'public', '{"people":[],"organizations":[],"countries":[],"topics":[]}');
