INSERT INTO documents (title, author, type, year, lang, source, publisher, isbn, pages, tags, keywords, drive_id, url, status, access_level, entities)
VALUES ('Imperial Grunts: On the Ground with the American Military, from Mongolia to the Philippines to Iraq and Beyond', 'Kaplan, Robert D.', 'book', NULL, 'BM', '', '', '', NULL, '{}', '{}', NULL, 'A fascinating, unprecedented first-hand look at the soldiers on the front lines on the Global War on Terror. Plunging deep into midst of some of the hottest conflicts on the globe, Robert D. Kaplan takes us through mud and jungle, desert and dirt to the men and women on the ground who are leading the charge against threats to American security. These soldiers, fighting in thick Colombian jungles or on dusty Afghani plains, are the forefront of the new American foreign policy, a policy being implemented one soldier at a time. As Kaplan brings us inside their thoughts, feelings, and operations, these modern grunts provide insight and understanding into the War on Terror, bringing the war, which sometimes seems so distant, vividly to life.', 'available', 'public', '{"people":[],"organizations":[],"countries":[],"topics":[]}');
