INSERT INTO documents (title, author, type, year, lang, source, publisher, isbn, pages, tags, keywords, drive_id, url, status, access_level, entities)
VALUES ('Kontroversi Al-Quran Thomas Jefferson', 'Spellberg, Denise A.', 'book', NULL, 'BM', '', '', 'Penerbit Alvabet', NULL, '{}', '{}', NULL, 'Pada 1765, sebelas tahun menjelang Deklarasi Kemerdekaan Amerika Serikat, Thomas Jefferson membeli Al-Qur''an. Rupanya, ini hanya menandai awal dan minatnya yang panjang terhadap Islam. Memang, setelah itu ia terus mencari sejumlah buku tentang bahasa, sejarah, dan perkembangan Timur Tengah. Jefferson pun intensif memahami Islam meskipun hal itu dinilai menghina keimanannya, sebuah sentimen umum yang berkalu di kalangan Protestan kala itu di Inggris dan Amerika. Syahdan, sejak 1776, Jefferson telah membayangkan kaum Muslim sebagai warga negara masa depan bagi negeri barunya, Amerika Serikat.
 
Buku ini mengungkapkan cerita penting yang sedikit diketahui ihwal riwayat kebebasan agama di Amerika Serikat, sebuah drama di mana Islam memainkan peran mengejutkan. Denise A. Spellberg menceritakan bagaimana para pendiri Amerika Serikat tertarik pada ide-ide Pencerahan perihal toleransi Muslim untuk menciptakan landasan-landasan praktis pemerintahan Amerika Serikat yang tengah sengit diperdebatkan. Dalam hal ini, kaum Muslim yang kala itu tidak diketahui eksistensinya di koloni itu, menjadi batas imajinasi terjauh bagi pluralisme keagamaan Amerika Serikat, yang juga mencakup kaum Yahudi dan Katolik sebagai Minoritas sebenarnya.
 
Kini, selagi kecurigaan Barat terhadap Islam terus hidup dan jumlah warga Muslim di Amerika Serikat tumbuh menjadi jutaan, cerita Spellberg yang mengungkap gagasan revolusioner para pendiri Amerika Serikat ini sangat penting untuk diketahui. Di tengah menguatnya keyakinan ihwal benturan peradaban antara Islam dan Barat, buku ini menjadi bacaan yang tepat untuk merajut kembali harapan akan perdamaian dunia.', 'available', 'public', '{"people":[],"organizations":[],"countries":[],"topics":[]}');
INSERT INTO documents (title, author, type, year, lang, source, publisher, isbn, pages, tags, keywords, drive_id, url, status, access_level, entities)
