INSERT INTO documents (title, author, type, year, lang, source, publisher, isbn, pages, tags, keywords, drive_id, url, status, access_level, entities)
VALUES ('liberalisme arab', 'Recker, Clemens', 'book', NULL, 'BM', '', '', '', NULL, '{}', '{}', NULL, 'Apadah ada liberalisme di dunia Arab?Salah satu tujuan penerbitan buku ini adalah untuk membangkitkan kembali warisan liberal dalam sejarah pemikiran Arab dengan mengemukakan capaian-capaian gagasannya dalam tujuh kategori pemikiran liberal yang paling mendasar kebebasan individu, penegakan hukum, ekonomi pasar, demorasi, sekularisme, pendidikan dan hak-hak perempuan.
 
In a nutshell, this book summarizes and explains the ideas from several top Arab liberal thinkers in the modern history of the region. This book was also presented to the public in Cairo, Beirut, and Amman and well received there. This is the “inner voice” of the liberal Arab and Muslims in order to build a bridge between them and their predecessors and emphasize that liberalism truly has a strong and deep root in Arab political thinking.', 'available', 'public', '{"people":[],"organizations":[],"countries":[],"topics":[]}');
