INSERT INTO documents (title, author, type, year, lang, source, publisher, isbn, pages, tags, keywords, drive_id, url, status, access_level, entities)
VALUES ('The American Role in Vietnam and East Asia: Between Two Revolutions', 'Kenny, Henry J.', 'book', NULL, 'BM', '', '', 'Praeger Publishers Inc.', NULL, '{}', '{}', NULL, 'This study puts the Vietnam experience in the perspective of events taking place in the Far East during the post World War II era, and relates the unfolding scene to the future of U.S. involvement in that part of the world. The author provides an historical analysis of the war and the American power and influence which followed. He then addresses the tremendous economic, political, and strategic changes that took place on the larger East Asian scene both during and after the war. Finally, the book considers specific issues of American involvement, with special attention to the two most important countries of the region--China and Japan.', 'available', 'public', '{"people":[],"organizations":[],"countries":[],"topics":[]}');
