INSERT INTO documents (title, author, type, year, lang, source, publisher, isbn, pages, tags, keywords, drive_id, url, status, access_level, entities)
VALUES ('The Post-American World', 'Zakaria, Fareed', 'book', NULL, 'BM', '', '', 'W. W. Norton Company', NULL, '{}', '{}', NULL, '"This is not a book about the decline of America, but rather about the rise of everyone else." So begins Fareed Zakaria''s important new work on the era we are now entering. 
 
Following on the success of his best-selling The Future of Freedom, Zakaria describes with equal prescience a world in which the United States will no longer dominate the global economy, orchestrate geopolitics, or overwhelm cultures. He sees the "rise of the rest"—the growth of countries like China, India, Brazil, Russia, and many others—as the great story of our time, and one that will reshape the world. 
 
The tallest buildings, biggest dams, largest-selling movies, and most advanced cell phones are all being built outside the United States. This economic growth is producing political confidence, national pride, and potentially international problems. How should the United States understand and thrive in this rapidly changing international climate? What does it mean to live in a truly global era? Zakaria answers these questions with his customary lucidity, insight, and imagination.', 'available', 'public', '{"people":[],"organizations":[],"countries":[],"topics":[]}');
INSERT INTO documents (title, author, type, year, lang, source, publisher, isbn, pages, tags, keywords, drive_id, url, status, access_level, entities)
VALUES ('The Power Broker: Robert Moses and the Fall of New York', 'Caro, Robert A.', 'book', NULL, 'BM', '', '', 'Vintage Books', NULL, '{}', '{}', NULL, 'One of the most acclaimed books of our time, winner of both the Pulitzer and the Francis Parkman prizes, The Power Broker tells the hidden story behind the shaping (and mis-shaping) of twentieth-century New York (city and state) and makes public what few have known: that Robert Moses was, for almost half a century, the single most powerful man of our time in New York, the shaper not only of the city''s politics but of its physical structure and the problems of urban decline that plague us today.
 
 In revealing how Moses did it--how he developed his public authorities into a political machine that was virtually a fourth branch of government, one that could bring to their knees Governors and Mayors (from La Guardia to Lindsay) by mobilizing banks, contractors, labor unions, insurance firms, even the press and the Church, into an irresistible economic force--Robert Caro reveals how power works in all the cities of the United States. Moses built an empire and lived like an emperor. He personally conceived and completed public works costing 27 billion dollars--the greatest builder America (and probably the world) has ever known. Without ever having been elected to office, he dominated the men who were--even his most bitter enemy, Franklin D. Roosevelt, could not control him--until he finally encountered, in Nelson Rockefeller, the only man whose power (and ruthlessness in wielding it) equalled his own.', 'available', 'public', '{"people":[],"organizations":[],"countries":[],"topics":[]}');
