INSERT INTO documents (title, author, type, year, lang, source, publisher, isbn, pages, tags, keywords, drive_id, url, status, access_level, entities)
VALUES ('The Zionist Idea: A Historical Analysis and Reader', 'Hertzberg, Arthur', 'book', NULL, 'BM', '', '', '', NULL, '{}', '{}', NULL, 'A classic since its initial publication in 1959, The Zionist Idea is an anthology of writings by the leading thinkers of the Zionist movement, including Theodor Herzl, Ahad Ha-Am, Martin Buber, Louis Brandeis, Rabbi Abraham Isaac Kook, Judah Magnes, Max Nordau, Mordecai Kaplan, Vladimir Jabotinsky, Chaim Weizmann, and David Ben-Gurion.', 'available', 'public', '{"people":[],"organizations":[],"countries":[],"topics":[]}');
INSERT INTO documents (title, author, type, year, lang, source, publisher, isbn, pages, tags, keywords, drive_id, url, status, access_level, entities)
VALUES ('World at War (Picture This)', 'Cawthorne, Nigel', 'book', NULL, 'BM', '', '', '', NULL, '{}', '{}', NULL, 'World War II - one of the most defining periods of the 20th century, and the costliest war in terms of human life. World At War''s comprehensive account portrays the epic scale of combat while capturing personal courage and sacrifice.
 
Complete with official strategic maps, soldiers'' letters home and hundreds of striking photographs, this chronological, compelling and authoritative book reveals the conflict and upheaval, explaining how the war was won around the world.', 'available', 'public', '{"people":[],"organizations":[],"countries":[],"topics":[]}');
INSERT INTO documents (title, author, type, year, lang, source, publisher, isbn, pages, tags, keywords, drive_id, url, status, access_level, entities)
VALUES ('The Power Elite', 'C. Wright Mills', 'book', 1959, 'BM', '18khaFYgm-sLii1vVA1o51WwDl1D0rpTW', 'Oxford University Press', '', NULL, '{"423"}', '{"power elite","social stratification","political power","economic power","military power","American society"}', 'https://drive.google.com/file/d/18khaFYgm-sLii1vVA1o51WwDl1D0rpTW/view?usp=drivesdk', 'Buku ini menganalisis struktur kuasa di Amerika Syarikat, dengan fokus pada tiga institusi utama: ekonomi korporat, elit politik, dan kepimpinan tentera. Ia menghuraikan bagaimana elit-elit ini saling berkaitan dan membentuk "power elite" yang membuat keputusan penting yang mempengaruhi masyarakat.', 'digital', 'public', '{"people":[],"organizations":[],"countries":[],"topics":[]}');
